#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define OUTBUF_SIZE 1024
static char main_out[OUTBUF_SIZE];

static void to_snake(const char *src) {
    size_t out = 0;
    for (size_t i = 0; src[i] != '\0' && out + 1 < OUTBUF_SIZE; ++i) {
        unsigned char c = (unsigned char)src[i];
        if (isupper(c)) {
            if (out + 2 >= OUTBUF_SIZE) break;
            main_out[out++] = '_';
            main_out[out++] = (char)tolower(c);
        } else {
            main_out[out++] = (char)c;
        }
    }
    main_out[out] = '\0';
    puts(main_out);
}

static void to_camel(const char *src) {
    size_t out = 0;
    int capitalize_next = 0;
    for (size_t i = 0; src[i] != '\0' && out + 1 < OUTBUF_SIZE; ++i) {
        unsigned char c = (unsigned char)src[i];
        if (c == '_') {
            capitalize_next = 1;
            continue;
        }
        if (capitalize_next && islower(c)) {
            c = (unsigned char)toupper(c);
        }
        capitalize_next = 0;
        main_out[out++] = (char)c;
    }
    main_out[out] = '\0';
    puts(main_out);
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    if (strcmp(argv[1], "to_camel") == 0) {
        to_camel(argv[2]);
    } else if (strcmp(argv[1], "to_snake") == 0) {
        to_snake(argv[2]);
    } else {
        puts("INVALID_MODE");
    }
    return 0;
}
